                        `format`="zto"),
                    list(
                        `name`="aic", 
                        `title`="AIC", 
                        `type`="number"),
                    list(
                        `name`="brier", 
                        `title`="Brier Score", 
                        `type`="number", 
                        `format`="zto")),
                clearWith=list(
                    "showModelComparison",
                    "outcome",
                    "patientID",
                    "outcomeLevel",
                    "explanatory",
                    "lambda",
                    "penalty",
                    "alpha",
                    "nfolds",
                    "standardize",
                    "random_seed")))}))

lassologisticBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "lassologisticBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "ClinicoPath",
                name = "lassologistic",
                version = c(1,0,84),
                options = options,
                results = lassologisticResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'none')
        }))

#' LASSO Logistic Regression
#'
#' Performs LASSO-penalized logistic regression for variable selection in 
#' binary classification problems. Ideal for diagnostic pathology studies that 
#' build classifiers (e.g., tumor type A vs B) with automatic feature 
#' selection.
#' 
#' @param data The data as a data frame, with one independent observation per
#'   row.
#' @param outcome Binary outcome variable to classify. Can be factor or
#'   numeric with exactly two observed values.
#' @param outcomeLevel Level of the outcome that is the event (positive
#'   class), for example Malignant. Required for a nominal or ordinal outcome:
#'   it is never taken from the order of the levels, and until it is chosen the
#'   analysis shows the levels found and fits nothing. A numeric outcome coded
#'   0/1 is read as 1 = event without a choice; for any other numeric coding,
#'   set the outcome's measure type to Nominal and choose the level. From R the
#'   argument has no default: pass the level, or NULL for a 0/1 outcome.
#' @param explanatory Variables to be considered for selection. At least 2
#'   required. Constant variables are removed automatically.
#' @param penalty Type of regularization penalty. LASSO (L1) produces sparse
#'   models by setting coefficients to zero. Ridge (L2) shrinks but retains all.
#'   Elastic Net combines both.
#' @param alpha Mixing parameter for elastic net. Only used when penalty is
#'   elasticnet.
#' @param lambda Method for selecting the optimal lambda from
#'   cross-validation. 1SE rule tends to select fewer variables (more
#'   conservative).
#' @param nfolds Number of folds for cross-validation. Automatically reduced
#'   when sample size is limited.
#' @param random_seed Random seed for reproducible cross-validation fold
#'   assignment.
#' @param standardize Whether glmnet standardizes predictors within each
#'   training fold and bootstrap fit, using its population (1/n) standard
#'   deviation. Reported coefficients remain on the original measurement scale.
#' @param suitabilityCheck Check sample size, events-per-variable ratio,
#'   multicollinearity, and whether regularization is needed.
#' @param bootstrapValidation Perform bootstrap optimism-corrected validation
#'   (Harrell method). Reports corrected AUC, calibration slope, and Brier
#'   score. Scaling and lambda selection are repeated within every resample.
#'   Copies of an observation in a bootstrap sample remain in the same CV fold.
#' @param bootstrapN Number of bootstrap iterations for internal validation.
#' @param cv_plot Show cross-validation deviance vs lambda plot.
#' @param coef_plot Show bar plot of selected variable coefficients.
#' @param roc_plot Show ROC curve with AUC and confidence interval.
#' @param scoringSystem Convert model coefficients to an integer-point scoring
#'   system. Multiple methods available following published standards.
#' @param scoringMethod Method for converting each predictor's log-odds
#'   contribution (the coefficient times the contrast its criterion applies) to
#'   integer points. Beta10: multiply by 10 and round (the Beta10/integer method
#'   of Mehta et al. 2016). Smallest: divide by the smallest contribution and
#'   round, a Sullivan-type scale with one point per smallest contribution
#'   (Sullivan et al. 2004); contributions below 1e-8 of the largest are not
#'   used as the divisor. This option was previously labelled "Schneeweiss";
#'   Schneeweiss et al. 2003 instead add one point per 0.3 increase in the log
#'   odds ratio. Max-scaled: divide by the largest absolute coefficient and
#'   multiply by scoringMaxPoints, so the strongest predictor scores exactly the
#'   maximum. This option was previously labelled "Sullivan/D'Agostino"; it is
#'   not the Sullivan 2004 Framingham procedure, which awards points per
#'   category of each factor relative to a reference factor's per-category
#'   distance. Compare: generate all three and show performance comparison.
#'   Every method gives a selected predictor at least one point (of its sign)
#'   when its points would round to zero, and caps a single predictor at 1000
#'   points.
#' @param scoringMaxPoints Points assigned to the strongest predictor in the
#'   Max-scaled method. The Beta10 method uses a fixed x10 coefficient scaling
#'   and ignores this value; the Smallest method scales by the smallest
#'   contribution and also ignores it.
#' @param scoreCutMethod How continuous predictors are dichotomized when
#'   awarding points. A predictor earns its points when the patient's value
#'   exceeds this cut. 'median' (the default) splits at the sample median, which
#'   is data-derived and will differ in another cohort. 'manual' lets you enter
#'   established clinical thresholds. Fixed cutoffs alone do not establish
#'   transportability; the score still requires external validation.
#' @param scoreCutPoints Cut points on the ORIGINAL measurement scale, as
#'   'variable=value' pairs separated by commas or semicolons, e.g. 'ki67=20,
#'   age=65'. Used when Cut Point method is 'manual'. Any continuous predictor
#'   not listed falls back to the sample median, and that fallback is reported.
#'   Binary predictors ignore this - they score when present.
#' @param scoreLookupTable Generate a table listing each observed total score
#'   with its number of cases, events and observed (in-sample) event rate. These
#'   are proportions in this dataset, not model predictions.
#' @param showSummary Display a natural-language summary of the main results.
#' @param showExplanations Display explanations of LASSO logistic regression
#'   methodology.
#' @param showMethodologyNotes Show technical notes about regularization and
#'   validation.
#' @param includeClinicalGuidance Include guidance for clinical interpretation
#'   of results.
#' @param showVariableImportance Display variable importance rankings across
#'   lambda values.
#' @param showModelComparison Compare the selected penalized model with
#'   unpenalized logistic refits.
#' @param patientID Optional identifier for independent patients. Repeated or
#'   missing IDs among analyzed rows are rejected. Each row is otherwise assumed
#'   independent; repeated lesions, visits, or readings require a patient-level
#'   summary or a method that accounts for clustering.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notices} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$suitabilityReport} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$modelSummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$coefficients} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$performance} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$scoringTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$scoringPerformance} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$methodComparison} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$lookupTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$validationTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cv_plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$coef_plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$roc_plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$predictions} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$summaryText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$lassoExplanation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$methodologyNotes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$clinicalGuidance} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$variableImportance} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$modelComparison} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$modelSummary$asDF}
#'
#' \code{as.data.frame(results$modelSummary)}
#'
#' @export
lassologistic <- function(
    data,
    outcome,
    outcomeLevel,
    explanatory,
    penalty = "lasso",
    alpha = 0.5,
    lambda = "lambda.1se",
    nfolds = 10,
    random_seed = 123456,
    standardize = TRUE,
    suitabilityCheck = TRUE,
    bootstrapValidation = FALSE,
    bootstrapN = 200,
    cv_plot = TRUE,
    coef_plot = TRUE,
    roc_plot = TRUE,
    scoringSystem = FALSE,
    scoringMethod = "smallest",
    scoringMaxPoints = 10,
    scoreCutMethod = "median",
    scoreCutPoints = "",
    scoreLookupTable = TRUE,
    showSummary = FALSE,
    showExplanations = FALSE,
    showMethodologyNotes = FALSE,
    includeClinicalGuidance = FALSE,
    showVariableImportance = FALSE,
    showModelComparison = FALSE,
    patientID = NULL) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("lassologistic requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(explanatory)) explanatory <- jmvcore::resolveQuo(jmvcore::enquo(explanatory))
    if ( ! missing(patientID)) patientID <- jmvcore::resolveQuo(jmvcore::enquo(patientID))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(explanatory), explanatory, NULL),
            `if`( ! missing(patientID), patientID, NULL))


    options <- lassologisticOptions$new(
        outcome = outcome,
        outcomeLevel = outcomeLevel,
        explanatory = explanatory,
        penalty = penalty,
        alpha = alpha,
        lambda = lambda,
        nfolds = nfolds,
        random_seed = random_seed,
        standardize = standardize,
        suitabilityCheck = suitabilityCheck,
        bootstrapValidation = bootstrapValidation,
        bootstrapN = bootstrapN,
        cv_plot = cv_plot,
        coef_plot = coef_plot,
        roc_plot = roc_plot,
        scoringSystem = scoringSystem,
        scoringMethod = scoringMethod,
        scoringMaxPoints = scoringMaxPoints,
        scoreCutMethod = scoreCutMethod,
        scoreCutPoints = scoreCutPoints,
        scoreLookupTable = scoreLookupTable,
        showSummary = showSummary,
        showExplanations = showExplanations,
        showMethodologyNotes = showMethodologyNotes,
        includeClinicalGuidance = includeClinicalGuidance,
        showVariableImportance = showVariableImportance,
        showModelComparison = showModelComparison,
        patientID = patientID)

    analysis <- lassologisticClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

